-- CPF QA37 Manual EDU 135 durable execution ledger (V93)
CREATE TABLE CPF_EDU_OPERATION (
    EXECUTION_ID VARCHAR2(64) NOT NULL,
    REQUIREMENT_ID VARCHAR2(32) NOT NULL,
    BUSINESS_KEY VARCHAR2(200) NOT NULL,
    IDEMPOTENCY_KEY VARCHAR2(200) NOT NULL,
    PAYLOAD_HASH VARCHAR2(64) NOT NULL,
    ACTOR_ID VARCHAR2(128) NOT NULL,
    ACTOR_ROLES VARCHAR2(1000) NOT NULL,
    DATA_SCOPE VARCHAR2(500) NOT NULL,
    STATE VARCHAR2(40) NOT NULL,
    EXPECTED_VERSION NUMBER(19) NOT NULL,
    RECORD_VERSION NUMBER(19) NOT NULL,
    FENCING_TOKEN NUMBER(19) NOT NULL,
    RETRY_COUNT NUMBER(10) NOT NULL,
    MAX_RETRIES NUMBER(10) NOT NULL,
    FAILURE_POINT VARCHAR2(64) NOT NULL,
    RESULT_CODE VARCHAR2(64) NOT NULL,
    RESULT_MESSAGE VARCHAR2(1000) NOT NULL,
    REQUEST_ID VARCHAR2(64) NOT NULL,
    TRACE_ID VARCHAR2(64) NOT NULL,
    PAYLOAD_JSON CLOB NOT NULL,
    RESULT_JSON CLOB NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    COMPLETED_AT TIMESTAMP(6) NULL,
    CONSTRAINT PK_CPF_EDU_OPERATION PRIMARY KEY (EXECUTION_ID),
    CONSTRAINT UK_CPF_EDU_OPERATION_IDEM UNIQUE (REQUIREMENT_ID, IDEMPOTENCY_KEY)
);
CREATE INDEX IX_CPF_EDU_OPERATION_STATE ON CPF_EDU_OPERATION (STATE, UPDATED_AT);
CREATE INDEX IX_CPF_EDU_OPERATION_BIZ ON CPF_EDU_OPERATION (REQUIREMENT_ID, BUSINESS_KEY, CREATED_AT);
CREATE INDEX IX_CPF_EDU_OPERATION_TRACE ON CPF_EDU_OPERATION (TRACE_ID);

CREATE TABLE CPF_EDU_OPERATION_TARGET (
    TARGET_ID VARCHAR2(64) NOT NULL, EXECUTION_ID VARCHAR2(64) NOT NULL, TARGET_KEY VARCHAR2(200) NOT NULL,
    STATE VARCHAR2(40) NOT NULL, BEFORE_JSON CLOB NOT NULL, AFTER_JSON CLOB NOT NULL,
    ERROR_CODE VARCHAR2(64) NOT NULL, ERROR_MESSAGE VARCHAR2(1000) NOT NULL,
    TARGET_VERSION NUMBER(19) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_CPF_EDU_OPERATION_TARGET PRIMARY KEY (TARGET_ID),
    CONSTRAINT FK_CPF_EDU_TARGET_OPERATION FOREIGN KEY (EXECUTION_ID) REFERENCES CPF_EDU_OPERATION (EXECUTION_ID),
    CONSTRAINT UK_CPF_EDU_TARGET_KEY UNIQUE (EXECUTION_ID, TARGET_KEY)
);
CREATE INDEX IX_CPF_EDU_TARGET_STATE ON CPF_EDU_OPERATION_TARGET (EXECUTION_ID, STATE);

CREATE TABLE CPF_EDU_OPERATION_AUDIT (
    AUDIT_ID VARCHAR2(64) NOT NULL, EXECUTION_ID VARCHAR2(64) NOT NULL, REQUIREMENT_ID VARCHAR2(32) NOT NULL,
    ACTION VARCHAR2(64) NOT NULL, BEFORE_STATE VARCHAR2(40) NOT NULL, AFTER_STATE VARCHAR2(40) NOT NULL,
    ACTOR_ID VARCHAR2(128) NOT NULL, REASON VARCHAR2(1000) NOT NULL, TRACE_ID VARCHAR2(64) NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_CPF_EDU_OPERATION_AUDIT PRIMARY KEY (AUDIT_ID),
    CONSTRAINT FK_CPF_EDU_AUDIT_OPERATION FOREIGN KEY (EXECUTION_ID) REFERENCES CPF_EDU_OPERATION (EXECUTION_ID)
);
CREATE INDEX IX_CPF_EDU_AUDIT_TRACE ON CPF_EDU_OPERATION_AUDIT (TRACE_ID, CREATED_AT);

CREATE TABLE CPF_EDU_OUTBOX (
    EVENT_ID VARCHAR2(64) NOT NULL, EXECUTION_ID VARCHAR2(64) NOT NULL, DESTINATION VARCHAR2(200) NOT NULL,
    EVENT_KEY VARCHAR2(200) NOT NULL, PAYLOAD_JSON CLOB NOT NULL, STATE VARCHAR2(40) NOT NULL,
    ATTEMPT_COUNT NUMBER(10) NOT NULL, NEXT_ATTEMPT_AT TIMESTAMP(6) NOT NULL,
    CLAIMED_BY VARCHAR2(128) NOT NULL, FENCING_TOKEN NUMBER(19) NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_CPF_EDU_OUTBOX PRIMARY KEY (EVENT_ID),
    CONSTRAINT FK_CPF_EDU_OUTBOX_OPERATION FOREIGN KEY (EXECUTION_ID) REFERENCES CPF_EDU_OPERATION (EXECUTION_ID)
);
CREATE INDEX IX_CPF_EDU_OUTBOX_READY ON CPF_EDU_OUTBOX (STATE, NEXT_ATTEMPT_AT);

CREATE TABLE CPF_EDU_BUSINESS_RECORD (
    REQUIREMENT_ID VARCHAR2(32) NOT NULL,
    BUSINESS_KEY VARCHAR2(200) NOT NULL,
    DATA_SCOPE VARCHAR2(500) NOT NULL,
    BUSINESS_STATE VARCHAR2(64) NOT NULL,
    RECORD_VERSION NUMBER(19) NOT NULL,
    FENCING_TOKEN NUMBER(19) NOT NULL,
    PAYLOAD_JSON CLOB NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_CPF_EDU_BUSINESS_RECORD PRIMARY KEY (REQUIREMENT_ID, BUSINESS_KEY, DATA_SCOPE)
);
CREATE INDEX IX_CPF_EDU_BUSINESS_STATE ON CPF_EDU_BUSINESS_RECORD (REQUIREMENT_ID, BUSINESS_STATE, UPDATED_AT);
CREATE INDEX IX_CPF_EDU_BUSINESS_FENCE ON CPF_EDU_BUSINESS_RECORD (REQUIREMENT_ID, FENCING_TOKEN);

CREATE TABLE CPF_EDU_LEASE (
    LEASE_KEY VARCHAR2(240) NOT NULL, OWNER_ID VARCHAR2(128) NOT NULL,
    FENCING_TOKEN NUMBER(19) NOT NULL,
    EXPIRES_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_CPF_EDU_LEASE PRIMARY KEY (LEASE_KEY)
);

CREATE TABLE CPF_EDU_COUNTERPARTY_REQUEST (
    COUNTERPARTY_REQUEST_ID VARCHAR2(64) NOT NULL,
    REQUIREMENT_ID VARCHAR2(32) NOT NULL,
    IDEMPOTENCY_KEY VARCHAR2(200) NOT NULL,
    REQUEST_HASH VARCHAR2(64) NOT NULL,
    BUSINESS_KEY VARCHAR2(200) NOT NULL,
    FAMILY_CODE VARCHAR2(40) NOT NULL,
    SCENARIO_CODE VARCHAR2(40) NOT NULL,
    STATE VARCHAR2(40) NOT NULL,
    RESPONSE_STATUS NUMBER(10) NOT NULL,
    RESPONSE_JSON CLOB NOT NULL,
    ATTEMPT_COUNT NUMBER(10) NOT NULL,
    TRACE_ID VARCHAR2(64) NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    COMPLETED_AT TIMESTAMP(6) NULL,
    CONSTRAINT PK_CPF_EDU_COUNTERPARTY PRIMARY KEY (COUNTERPARTY_REQUEST_ID),
    CONSTRAINT UK_CPF_EDU_COUNTERPARTY_IDEM UNIQUE (REQUIREMENT_ID, IDEMPOTENCY_KEY)
);
CREATE INDEX IX_CPF_EDU_COUNTERPARTY_STATE ON CPF_EDU_COUNTERPARTY_REQUEST (STATE, UPDATED_AT);
CREATE INDEX IX_CPF_EDU_COUNTERPARTY_TRACE ON CPF_EDU_COUNTERPARTY_REQUEST (TRACE_ID, CREATED_AT);
